    count(x, y, n, c = 'fg', pad = 0) {
      const s = pad ? String(n).padStart(pad, '0') : String(n);
      const w = K.countWidth(s);
      return K.rect(x, y - 8, w, 16, 'pn', c === 'fg' ? 'ed' : c) + K.t(x + 4, y + 4, s, c);
    },
